<header class="page-head"><div><p class="eyebrow">Admin</p><h1>User Management</h1></div></header><section class="panel"><form id="userForm" class="form-grid wide"><input type="hidden" name="id"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="6"></label><label>Role<select name="role"><option value="customer">customer</option><option value="admin">admin</option></select></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn primary">Save User</button><button type="button" class="btn ghost" onclick="$('#userForm')[0].reset(); $('#userForm [name=id]').val('')">Clear</button></form></section><section class="panel"><table id="usersTable" class="display"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Phone</th><th>Action</th></tr></thead></table></section>
@endsection
@push('scripts')<script>function editUser(row){Object.keys(row).forEach(k=>$('#userForm [name='+k+']').val(row[k]));$('#userForm [name=password]').val('');}const usersTable=$('#usersTable').DataTable({ajax:'/api/users',columns:[{data:'id'},{data:'name'},{data:'email'},{data:'role'},{data:'phone'},{data:null,render:(d)=>`<button class="btn mini" onclick='editUser(${JSON.stringify(d)})'>Edit</button><button class="btn mini danger" onclick="ajaxDelete('/api/users/${d.id}',()=>usersTable.ajax.reload())">Delete</button>`}]});$('#userForm').on('submit',function(e){e.preventDefault();const id=$('[name=id]',this).val();ajaxForm(id?'/api/users/'+id:'/api/users',id?'PUT':'POST',$(this).serialize(),()=>{this.reset();$('[name=id]',this).val('');usersTable.ajax.reload();});});</script>@endpush
